<span class="line"><span style="color:#101820;">  router</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Get</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;/dashboard&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> dashboardController</span><span style="color:#68747D;">.</span><span style="color:#101820;">Index</span><span style="color:#68747D;">)</span></span>
